{
  "summary": "驗證專案任務的建立與更新 API (`POST /api/projects/{pid}/tasks` 及 `PATCH /api/tasks/{tid}`) 中 `title` 與 `priority` 欄位的正確性與邊界條件，確保違規輸入回傳 `422` 且不回傳 `5xx`。",
  "acceptance_criteria": [
    "title 欄位為必填，長度限制為 1 至 100 字元（包含邊界）。",
    "title 長度為 100 字元時應被接受，並回傳成功狀態碼（201 或 200）。",
    "title 長度超過 101 字元或為空白時，系統應回傳 422 錯誤，且不得回傳 5xx。",
    "priority 欄位必須為整數，有效範圍為 1 至 5（包含邊界），未填寫時預設為 3。",
    "priority 為 1 與 5 時應被接受；為 0 或 6 時系統應回傳 422 錯誤。"
  ]
}

{
  "cases": [
    {
      "id": "TC-1",
      "title": "Title boundary validation (1 and 100 characters)",
      "surface": "api",
      "steps": [
        "POST /api/projects with {\"name\": \"Project A\"} as alice",
        "POST /api/projects/{pid}/tasks with title of length 1 and default priority as alice",
        "POST /api/projects/{pid}/tasks with title of length 100 and default priority as alice"
      ],
      "expected": "title 欄位為必填，長度限制為 1 至 100 字元（包含邊界）。title 長度為 100 字元時應被接受，並回傳成功狀態碼（201 或 200）。"
    },
    {
      "id": "TC-2",
      "title": "Title violation validation (>101 characters or empty)",
      "surface": "api",
      "steps": [
        "POST /api/projects with {\"name\": \"Project A\"} as alice",
        "POST /api/projects/{pid}/tasks with title of length 101 as alice",
        "POST /api/projects/{pid}/tasks with title as empty string as alice"
      ],
      "expected": "title 長度超過 101 字元或為空白時，系統應回傳 422 錯誤，且不得回傳 5xx。"
    },
    {
      "id": "TC-3",
      "title": "Priority default and boundary validation (1, 3, 5)",
      "surface": "api",
      "steps": [
        "POST /api/projects with {\"name\": \"Project A\"} as alice",
        "POST /api/projects/{pid}/tasks with title 'Task' and no priority as alice",
        "POST /api/projects/{pid}/tasks with title 'Task' and priority 1 as alice",
        "POST /api/projects/{pid}/tasks with title 'Task' and priority 5 as alice"
      ],
      "expected": "priority 欄位必須為整數，有效範圍為 1 至 5（包含邊界），未填寫時預設為 3。priority 為 1 與 5 時應被接受"
    },
    {
      "id": "TC-4",
      "title": "Priority violation validation (0 and 6)",
      "surface": "api",
      "steps": [
        "POST /api/projects with {\"name\": \"Project A\"} as alice",
        "POST /api/projects/{pid}/tasks with title 'Task' and priority 0 as alice",
        "POST /api/projects/{pid}/tasks with title 'Task' and priority 6 as alice"
      ],
      "expected": "priority 為 1 與 5 時應被接受；為 0 或 6 時系統應回傳 422 錯誤。"
    }
  ]
}

